// Generate TypeScript types from ../schemas/*.json (exported by `ignis schemas export`, Rust contracts).
// All contract types are merged into one schema so shared $defs (Derivation, Measured, ...) are
// declared once. Output: src/contracts/generated.ts (do not edit by hand).
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { compile } from "json-schema-to-typescript";

const here = dirname(fileURLToPath(import.meta.url));
const schemasDir = join(here, "..", "..", "schemas");
const index = JSON.parse(readFileSync(join(schemasDir, "index.json"), "utf8"));
// Property-level "title"s would become one exported alias per field; keep titles on named types only.
const untitle = (node, keep = false) => {
  if (Array.isArray(node)) return node.map((n) => untitle(n));
  if (node && typeof node === "object") {
    const out = {};
    for (const [k, v] of Object.entries(node)) if (k !== "title" || keep) out[k] = untitle(v);
    return out;
  }
  return node;
};
const defs = {};
for (const name of index.types) {
  const s = JSON.parse(readFileSync(join(schemasDir, `${name}.json`), "utf8"));
  for (const [k, v] of Object.entries(s.$defs ?? {})) {
    // schemars emits nested $defs without a title; the def name is the type name.
    const u = { title: k, ...untitle(v, true) };
    if (defs[k] && JSON.stringify(defs[k]) !== JSON.stringify(u)) throw new Error(`conflicting $def ${k} in ${name}`);
    defs[k] = u;
  }
  const { $defs, $id, $schema, ...body } = s;
  const u = { title: name, ...untitle(body, true) };
  if (defs[name] && JSON.stringify(defs[name]) !== JSON.stringify(u)) throw new Error(`conflicting top-level ${name}`);
  defs[name] = u;
}
const unused = readdirSync(schemasDir).filter((f) => f.endsWith(".json") && f !== "index.json" && !index.types.includes(f.slice(0, -5)));
if (unused.length) console.warn("schemas not listed in index.json:", unused);
const root = {
  title: "IgnisContracts",
  type: "object",
  additionalProperties: false,
  properties: Object.fromEntries(index.types.map((n) => [n, { $ref: `#/$defs/${n}` }])),
  $defs: defs,
};
const ts = await compile(root, "IgnisContracts", {
  bannerComment: `/* Generated by \`npm run gen:types\` from schemas/*.json (schema_version ${index.schema_version}). Do not edit. */`,
  additionalProperties: false,
  unreachableDefinitions: true,
  strictIndexSignatures: false,
  format: true,
});
const out = join(here, "..", "src", "contracts", "generated.ts");
const text = ts + `\nexport const SCHEMA_VERSION = "${index.schema_version}";\n`;
if (process.argv.includes("--check")) {
  // Drift gate: generated.ts must equal what the committed schemas produce.
  const current = readFileSync(out, "utf8").replace(/\r\n/g, "\n");
  if (current !== text) {
    console.error("src/contracts/generated.ts is stale: run `ignis schemas export`, then `npm run gen:types`");
    process.exit(1);
  }
  console.log(`generated.ts matches ${index.types.length} contract schemas`);
} else {
  writeFileSync(out, text);
  console.log(`generated ${index.types.length} contract types`);
}
